mod prepared;mod table_oracle;
use hec_native_ic::{counted,fp::Fp,poly::Poly,instance::{thread_curve,factor_base},oracle,rng::Rng};
fn roots_native(r:Option<oracle::Roots>)->Option<Vec<(u64,u32)>>{r.map(|x|x.as_slice().to_vec())}
fn roots_table(r:Option<table_oracle::Roots>)->Option<Vec<(u64,u32)>>{r.map(|x|x.as_slice().to_vec())}
fn brute(u:&Poly,fp:&Fp)->Option<Vec<(u64,u32)>>{let mut rest=*u;let mut out=vec![];for x in 0..fp.p{let mut m=0;while rest.deg()>0&&rest.eval(x,fp)==0{rest=rest.div_exact(&Poly::x_minus(x,fp),fp);m+=1;}if m>0{out.push((x,m));}}if rest.deg()==0{Some(out)}else{None}}
fn check(u:&Poly,fp:&Fp,table:&prepared::RootTable,independent:bool){let mut native=oracle::OracleStats::default();let mut cached=table_oracle::OracleStats::default();let a=roots_native(oracle::split(u,fp,&mut native));let b=roots_table(table_oracle::split(u,fp,&mut cached,table));assert_eq!(a,b);assert_eq!((native.calls,native.parity_rejects,native.frobenius,native.smooth),(cached.calls,cached.parity_rejects,cached.frobenius,cached.smooth));if independent{assert_eq!(b,brute(u,fp));}}
fn verify_table(fp:&Fp,table:&prepared::RootTable){let mut independent=vec![None;fp.p as usize];for y in 0..fp.p{let x=fp.mul(y,y);let slot=&mut independent[x as usize];if slot.map_or(true,|old|y<old){*slot=Some(y);}}assert_eq!(independent,table.roots);for a in 0..fp.p{let native=fp.sqrt(a).map(|x|x.min(fp.neg(x)));assert_eq!(native,table.sqrt(a,fp));assert_eq!(fp.legendre(a),table.legendre(a,fp));}assert_eq!(table.roots.iter().filter(|v|v.is_some()).count() as u64,(fp.p+1)/2);}
fn main(){counted::disable();let mut exhaustive=0;
 for p in[5u64,7,11]{let fp=Fp::new(p);let table=prepared::RootTable::build(&fp);verify_table(&fp,&table);let mut n=0;for degree in 0..=4{for mut code in 0..p.pow(degree as u32){let mut cs=vec![0;degree+1];for j in 0..degree{cs[j]=code%p;code/=p;}cs[degree]=1;check(&Poly::from_coeffs(&cs),&fp,&table,true);n+=1;}}exhaustive+=n;println!("EXHAUSTIVE p={p} degrees=0..4 polynomials={n} legacy_and_brute_equal=true");}
 let mut models=0;let mut samples=0;for line in include_str!("INSTANCES.tsv").lines().skip(1){let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let cc:u64=v[2].parse().unwrap();let c=thread_curve(p,cc,g).unwrap();assert_eq!(c.f.c[..c.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let prepared=prepared::prepare(&c,true);assert_eq!(prepared.fb,factor_base(&c));verify_table(&c.fp,&prepared.roots);prepared.roots.reset_lookups();let mut rng=Rng::new(2026111900^p^((g as u64)<<32));
 for j in 0..512{let degree=j%5;let mut cs:Vec<_>=(0..degree).map(|_|rng.below(p)).collect();cs.push(1);check(&Poly::from_coeffs(&cs),&c.fp,&prepared.roots,false);samples+=1;}
 println!("MODEL g={g} p={p} c={cc} catalogue={} all_x_values_and_root_table_exact=true oracle_samples=512 root_bytes={} sqrt_lookups={} legendre_lookups={}",prepared.fb.len(),prepared.roots.bytes(),prepared.roots.sqrt_lookups.get(),prepared.roots.legendre_lookups.get());models+=1;
 }assert_eq!(models,11);assert_eq!(samples,5632);eprintln!("PASS initial_native_models={models} exhaustive_polynomials={exhaustive} additional_polynomials={samples} all_catalogues_ordered_identical=true all_field_roots_canonical_exact=true oracle_decisions_multiplicities_stats_exact=true cap_p65537=true no_free_cross_call_cache=true no_speed_claim=true");}
